<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { MODS, catsFor } from '@/core/modules'
import { SCENES, applySceneTheme, currentSceneId } from '@/core/scenes'
import { readSession } from '@/core/auth'
import { caseRepository } from '@/domain/case/repository'
import { undoLast } from '@/core/undo'

const route = useRoute(); const router = useRouter()
const drawer = ref(false); const toolsOpen = ref(false); const dark = ref(document.documentElement.classList.contains('dark')); const searchOpen = ref(false); const searchQuery = ref(''); const searchTick = ref(0); const undoVisible = ref(false)
const scene = computed(() => SCENES[currentSceneId()])
const isMobile = ref(window.innerWidth < 900)
const cats = computed(() => catsFor(currentSceneId()).filter(item => item.id !== 'all'))
const active = computed(() => route.name === 'home' ? 'home' : route.name === 'cases' || route.name === 'case' ? 'cases' : route.name === 'admin' ? 'admin' : String(route.params.id || ''))
const initials = computed(() => (readSession()?.u?.[0] || 'B').toUpperCase())
const searchResults = computed(() => { void searchTick.value; const q = searchQuery.value.trim().toLowerCase(); return q ? caseRepository.list().filter(item => `${item.title} ${item.problem} ${item.desiredOutcome}`.toLowerCase().includes(q)).slice(0, 8) : caseRepository.list().slice().sort((a, b) => b.updatedAt - a.updatedAt).slice(0, 8) })
function go(path: string) { drawer.value = false; router.push(path) }
function openSearch() { searchOpen.value = true; searchQuery.value = ''; requestAnimationFrame(() => document.querySelector<HTMLInputElement>('.global-search input')?.focus()) }
function closeSearch() { searchOpen.value = false }
function goCase(id: string) { closeSearch(); router.push('/app/cases/' + id) }
function resize() { isMobile.value = window.innerWidth < 900 }
function toggleTheme() { dark.value = !dark.value; document.documentElement.classList.toggle('dark', dark.value); localStorage.setItem('b_theme', dark.value ? 'dark' : 'light') }
function onKeydown(event: KeyboardEvent) { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); openSearch() } else if (event.key === 'Escape') closeSearch() }
function onDataSynced() { searchTick.value++ }
function onUndoAvailable() { undoVisible.value = true; window.setTimeout(() => { undoVisible.value = false }, 8000) }
function undo() { undoVisible.value = !undoLast(); }
onMounted(() => { applySceneTheme(currentSceneId()); window.addEventListener('resize', resize); window.addEventListener('keydown', onKeydown); window.addEventListener('beryl-data-synced', onDataSynced); window.addEventListener('beryl-undo-available', onUndoAvailable) })
onUnmounted(() => { window.removeEventListener('resize', resize); window.removeEventListener('keydown', onKeydown); window.removeEventListener('beryl-data-synced', onDataSynced); window.removeEventListener('beryl-undo-available', onUndoAvailable) })
</script>

<template>
  <div class="app-shell">
    <aside v-if="!isMobile" class="sidebar">
      <button class="brand" @click="go('/app/home')"><span class="brand-mark">B</span><span><b class="font-title">beryl</b><small>个人运行系统</small></span></button>
      <nav class="primary-nav">
        <button :class="{ on: active === 'home' }" @click="go('/app/home')"><i>⌂</i>工作台</button>
        <button :class="{ on: active === 'cases' }" @click="go('/app/cases')"><i>◈</i>现实课题</button>
        <button :class="{ on: active === 'inbox' }" @click="go('/app/module/inbox')"><i>↓</i>收集箱</button>
      </nav>
      <div class="tool-block"><button class="tools-title" @click="toolsOpen = !toolsOpen"><span>工具箱</span><i :class="{ rotate: toolsOpen }">⌄</i></button><div v-show="toolsOpen" class="tools-list"><template v-for="cat in cats" :key="cat.id"><p>{{ cat.name }}</p><button v-for="id in cat.mods.filter(id => id !== 'inbox')" :key="id" :class="{ on: active === id }" @click="go('/app/module/' + id)"><span>{{ MODS[id].icon }}</span>{{ MODS[id].name }}</button></template></div></div>
      <div class="sidebar-foot"><button @click="openSearch">⌕　搜索课题 <kbd>Ctrl K</kbd></button><button @click="go('/scene')">{{ scene.icon }} {{ scene.name }}</button><button @click="toggleTheme">{{ dark ? '☀' : '◐' }} {{ dark ? '浅色界面' : '深色界面' }}</button><button @click="go('/app/admin')">{{ initials }}　设置与同步</button></div>
    </aside>

    <header v-else class="mobile-header"><button class="brand compact" aria-label="返回工作台" @click="go('/app/home')"><span class="brand-mark">B</span><b class="font-title">beryl</b></button><div><button class="search-btn" aria-label="搜索课题" @click="openSearch">⌕</button><button class="menu" aria-label="打开菜单" @click="drawer = true">☰</button></div></header>
    <main class="page-container"><RouterView /></main>
    <nav v-if="isMobile" class="bottom-nav"><button :class="{ on: active === 'home' }" @click="go('/app/home')"><span>⌂</span>工作台</button><button :class="{ on: active === 'cases' }" @click="go('/app/cases')"><span>◈</span>课题</button><button :class="{ on: active === 'inbox' }" @click="go('/app/module/inbox')"><span>↓</span>收集箱</button><button @click="drawer = true"><span>⋯</span>更多</button></nav>
    <el-drawer v-model="drawer" direction="rtl" size="min(84vw,330px)" :with-header="false"><div class="drawer"><button class="brand" @click="go('/app/home')"><span class="brand-mark">B</span><span><b class="font-title">beryl</b><small>个人运行系统</small></span></button><div class="drawer-links"><button @click="openSearch">⌕ 搜索课题</button><button @click="go('/scene')">{{ scene.icon }} 切换场景</button><button @click="toggleTheme">{{ dark ? '☀' : '◐' }} 切换外观</button><button @click="go('/app/admin')">⚙ 设置与同步</button><p>工具箱</p><button v-for="cat in cats" :key="cat.id" class="cat-label" disabled>{{ cat.name }}</button><button v-for="id in cats.flatMap(cat => cat.mods).filter(id => id !== 'inbox')" :key="id" :class="{ on: active === id }" @click="go('/app/module/' + id)">{{ MODS[id].icon }}　{{ MODS[id].name }}</button></div></div></el-drawer>
    <div v-if="searchOpen" class="search-overlay" @click.self="closeSearch"><div class="search-panel beryl-card"><div class="search-head"><span>⌕</span><el-input v-model="searchQuery" class="global-search" placeholder="搜索课题、问题或目标…" /><button @click="closeSearch">Esc</button></div><div class="search-results"><button v-for="item in searchResults" :key="item.id" @click="goCase(item.id)"><span>{{ item.currentPhase === 'wood' ? '🌱' : item.currentPhase === 'fire' ? '🔥' : item.currentPhase === 'earth' ? '⛰️' : item.currentPhase === 'metal' ? '⚖️' : '💧' }}</span><span class="result-copy"><b>{{ item.title }}</b><small>{{ item.problem || item.desiredOutcome || '打开课题' }}</small></span><i>→</i></button><p v-if="!searchResults.length" class="no-results">没有匹配的课题</p></div></div></div>
    <div v-if="undoVisible" class="undo-bar"><span>已删除一条记录</span><button @click="undo">撤销</button></div>
  </div>
</template>

<style scoped>
.app-shell{min-height:100vh;display:flex}.sidebar{width:252px;padding:22px 14px 14px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column;background:var(--c-topbar);border-right:1px solid var(--c-border-soft);backdrop-filter:blur(16px)}.brand{border:0;background:transparent;color:var(--c-text);display:flex;align-items:center;gap:11px;text-align:left;cursor:pointer;padding:6px 8px}.brand-mark{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;background:var(--scene);color:white;font:600 22px var(--font-title);box-shadow:0 6px 14px var(--scene-glow-strong)}.brand b{font-size:23px;line-height:20px;display:block}.brand small{display:block;margin-top:4px;color:var(--c-text-3);font-size:10px;letter-spacing:.08em}.primary-nav{display:grid;gap:4px;margin:32px 0 20px}.primary-nav button,.tools-list button,.sidebar-foot button,.drawer-links button{border:0;background:transparent;color:var(--c-text-2);padding:10px 12px;border-radius:10px;text-align:left;cursor:pointer;font-size:13px}.primary-nav button:hover,.tools-list button:hover,.sidebar-foot button:hover,.drawer-links button:hover{background:var(--c-hover);color:var(--c-text)}.primary-nav button.on,.tools-list button.on,.drawer-links button.on{background:var(--scene-soft);color:var(--scene);font-weight:700}.primary-nav i{font-style:normal;font-size:18px;width:22px;display:inline-block}.tool-block{border-top:1px solid var(--c-border-soft);padding-top:14px}.tools-title{border:0;background:transparent;width:100%;display:flex;justify-content:space-between;color:var(--c-text-3);font-size:11px;letter-spacing:.08em;padding:4px 10px;cursor:pointer}.tools-title i{font-style:normal;transition:.2s}.tools-title i.rotate{transform:rotate(180deg)}.tools-list{display:grid;gap:2px;margin-top:8px}.tools-list p{font-size:10px;color:var(--c-text-3);margin:12px 10px 3px}.tools-list button span{display:inline-block;width:22px}.sidebar-foot{margin-top:auto;display:grid;gap:2px;border-top:1px solid var(--c-border-soft);padding-top:12px}.sidebar-foot button{font-size:11px}.mobile-header{height:62px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;background:var(--c-topbar);position:sticky;top:0;z-index:20;backdrop-filter:blur(14px);border-bottom:1px solid var(--c-border-soft)}.compact{padding:0}.compact .brand-mark{width:31px;height:31px;font-size:19px}.compact b{font-size:22px}.menu{border:1px solid var(--c-border);background:var(--c-card);border-radius:9px;width:36px;height:36px;color:var(--c-text);font-size:17px}.bottom-nav{position:fixed;z-index:20;bottom:0;left:0;right:0;display:flex;justify-content:space-around;background:var(--c-topbar);border-top:1px solid var(--c-border-soft);backdrop-filter:blur(16px);padding:7px 8px max(7px,env(safe-area-inset-bottom))}.bottom-nav button{border:0;background:transparent;color:var(--c-text-3);font-size:10px;display:grid;gap:2px;place-items:center;min-width:58px}.bottom-nav span{font-size:19px}.bottom-nav button.on{color:var(--scene);font-weight:700}.drawer{padding:24px 12px}.drawer-links{display:grid;gap:3px;margin-top:28px}.drawer-links p{font-size:10px;color:var(--c-text-3);letter-spacing:.08em;margin:18px 12px 4px}.drawer-links .cat-label{padding:5px 12px;color:var(--c-text-3);font-size:10px;cursor:default}
.sidebar-foot kbd{float:right;font-size:9px;color:var(--c-text-3);border:1px solid var(--c-border-soft);padding:1px 4px;border-radius:4px}.mobile-header>div{display:flex;gap:6px}.search-btn{border:1px solid var(--c-border);background:var(--c-card);border-radius:9px;width:36px;height:36px;color:var(--c-text);font-size:17px}.search-overlay{position:fixed;inset:0;z-index:80;background:color-mix(in srgb,var(--c-bg) 72%,transparent);backdrop-filter:blur(8px);padding:12vh 20px}.search-panel{max-width:640px;margin:0 auto;overflow:hidden}.search-head{display:flex;align-items:center;gap:8px;padding:12px 14px;border-bottom:1px solid var(--c-border-soft)}.search-head>span{font-size:22px;color:var(--scene)}.search-head button{border:0;background:transparent;color:var(--c-text-3);font-size:10px}.global-search{flex:1}.global-search :deep(input){border:0;box-shadow:none;background:transparent;font-size:15px}.search-results{padding:8px}.search-results button{display:flex;align-items:center;gap:10px;width:100%;border:0;background:transparent;color:var(--c-text);padding:10px;border-radius:8px;text-align:left;cursor:pointer}.search-results button:hover{background:var(--c-hover)}.result-copy{flex:1;display:grid;gap:3px}.result-copy b{font-size:13px}.result-copy small{font-size:10px;color:var(--c-text-3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.search-results i{color:var(--scene)}.no-results{text-align:center;color:var(--c-text-3);font-size:12px;padding:24px}.undo-bar{position:fixed;z-index:90;left:50%;bottom:24px;transform:translateX(-50%);display:flex;align-items:center;gap:18px;padding:10px 14px;border:1px solid var(--c-border);border-radius:10px;background:var(--c-card);box-shadow:0 8px 30px rgba(0,0,0,.14);font-size:12px}.undo-bar button{border:0;background:transparent;color:var(--scene);font-weight:700;cursor:pointer}
</style>
